import numpy as np
from scipy.spatial.transform import Rotation as R

def tx(x):
 T=np.eye(4);T[0,3]=x;return T
def tz(z):
 T=np.eye(4);T[2,3]=z;return T
def rz(x):
 T=np.eye(4);T[:3,:3]=R.from_euler('z',x).as_matrix();return T
def rx(x):
 T=np.eye(4);T[:3,:3]=R.from_euler('x',x).as_matrix();return T
q=[0,-1.04758,0,-2.63996,0,1.53564,-2.32]
for shift in [0,.107,.21]:
 T=np.eye(4)
 for alpha,a,d,qi in [(0,0,.333,q[0]),(-np.pi/2,0,0,q[1]),(np.pi/2,0,.316,q[2]),(np.pi/2,.0825,0,q[3]),(-np.pi/2,-.0825,.384,q[4]),(np.pi/2,0,0,q[5]),(np.pi/2,.088,0,q[6])]:T=T@rx(alpha)@tx(a)@rz(qi)@tz(d)
 T=T@tz(shift)
 print(shift,T[:3,3],R.from_matrix(T[:3,:3]).as_quat())
